  'Aloo paratha and curd': ['गव्हाचे पीठ, मीठ व पाणी घालून मऊ कणीक मळा; १५ मिनिटे ठेवा.', 'बटाटे उकडून कुस्करा; मिरची, कोथिंबीर व मीठ मिसळा.', 'कणकेच्या गोळ्यात सारण भरून नीट बंद करा आणि हळुवार लाटा.', 'गरम तव्यावर तूप लावून दोन्ही बाजूंनी सोनेरी ठिपके येईपर्यंत भाजा.', 'ताज्या दह्यासोबत गरम वाढा.'],
  'Rava idli and chutney': ['रवा ३–४ मिनिटे कोरडा भाजून थंड करा; फेटलेले दही, मीठ व पाणी घालून घट्ट पीठ करा; २० मिनिटे ठेवा.', 'थोड्या तेलात मोहरी, कढीपत्ता व मिरचीची फोडणी करून पिठात मिसळा.', 'इडलीच्या साच्यांना तेल लावून पीठ भरा; १०–१२ मिनिटे वाफवा; सुरी स्वच्छ बाहेर आली पाहिजे.', 'ओले खोबरे, मिरची, थोडे दही/पाणी व मीठ वाटून गुळगुळीत चटणी करा.', 'गरम इडली चटणीसोबत वाढा.'],
  'Zunka-bhakri': ['तेल गरम करून मोहरी, जिरे, लसूण व हिरवी मिरचीची फोडणी करा.', 'चिरलेला कांदा घालून मऊ व हलका सोनेरी होईपर्यंत परता.', 'आच कमी करून बेसन हळूहळू घालत ढवळा म्हणजे गुठळ्या होणार नाहीत; मीठ व थोडे पाणी शिंपडा.', 'झाकण ठेवून ५–७ मिनिटे अधूनमधून ढवळत कोरडा व मोकळा होईपर्यंत शिजवा.', 'ज्वारीच्या भाकरीसोबत गरम वाढा.'],
  'Dal tadka and jeera rice': ['तूरडाळ धुवून हळद व मीठ घालून कुकरमध्ये अगदी मऊ शिजवा; हलकी घोटा.', 'भात एक चमचा तूप व जिऱ्यासह मोकळा शिजवा.', 'तूप गरम करून जिरे, लसणाचे काप व चिरलेला टोमॅटो मऊ होईपर्यंत परता.', 'ही फोडणी डाळीवर घालून ३–४ मिनिटे उकळा.', 'जिरा भातासोबत डाळ वाढा.'],
  'Bhendi masala and chapati': ['भेंडी धुवून पूर्ण कोरडी करा आणि गोल चकत्या चिरा म्हणजे चिकटपणा येणार नाही.', 'थोड्या तेलात मध्यम आचेवर चिकटपणा जाईपर्यंत परतून बाजूला काढा.', 'कांदा-टोमॅटो मसाल्यासह परतून घट्ट मसाला करा.', 'भेंडी व मीठ घालून हलके मिसळा आणि झाकून ५ मिनिटे शिजवा.', 'ताज्या चपातीसोबत गरम वाढा.'],
  'Paneer bhurji and chapati': ['पनीर हाताने जाडसर कुस्करा.', 'तेलात कांदा व हिरवी मिरची मऊ होईपर्यंत परता; टोमॅटो व मसाले घालून तेल सुटेपर्यंत शिजवा.', 'पनीर व मीठ घालून ३–४ मिनिटे हलके परता; जास्त शिजवू नका.', 'वरून चिरलेली कोथिंबीर घाला.', 'चपातीसोबत गरम वाढा.'],
  'Shev bhaji and bhakri': ['तेल गरम करून मोहरी घाला, मग चिरलेला कांदा सोनेरी होईपर्यंत परता.', 'टोमॅटो, गोडा मसाला व मीठ घालून घट्ट झणझणीत ग्रेव्ही करा; रस्स्यासाठी पाणी घाला.', 'थोडे ओले खोबरे घालून ५ मिनिटे उकळा.', 'वाढण्याआधी जाड शेव घाला म्हणजे ती थोडी कडक राहील.', 'भाकरीसोबत गरम वाढा.'],
  'Pav bhaji': ['बटाटा, फ्लॉवर व मटार अगदी मऊ उकडून जाडसर कुस्करा.', 'लोणी गरम करून टोमॅटो व मसाले घालून घट्ट पेस्ट करा.', 'कुस्करलेल्या भाज्या थोडे पाणी घालून १० मिनिटे उकळत घोटून शिजवा.', 'वरून थोडे अजून लोणी घाला.', 'पाव लोण्यावर भाजून गरम भाजीसोबत वाढा.'],
  'Mushroom masala and chapati': ['मशरूम ओल्या कापडाने पुसून स्वच्छ करा (भिजवू नका) आणि कापा.', 'तेलात कांदा सोनेरी होईपर्यंत परता; टोमॅटो व मसाले घालून घट्ट मसाला करा.', 'मशरूम व मीठ घालून जास्त आचेवर ६–८ मिनिटे पाणी आटेपर्यंत शिजवा.', 'आणखी २ मिनिटे उकळा आणि मीठ पाहा.', 'चपातीसोबत गरम वाढा.'],
  'Aloo gobi and chapati': ['बटाटा व फ्लॉवर मध्यम फोडी करून नीट धुवा.', 'तेल गरम करून जिरे, मग टोमॅटो, हळद व मीठ घालून मऊ होईपर्यंत शिजवा.', 'आधी बटाटा व थोडे पाणी घालून झाकून ५ मिनिटे शिजवा.', 'फ्लॉवर घालून झाकून दोन्ही मऊ होईपर्यंत हलके ढवळत शिजवा.', 'चपातीसोबत गरम वाढा.'],
  'Tomato saar and rice': ['टोमॅटो थोड्या पाण्यात उकडून मिक्सरमध्ये गुळगुळीत प्युरी करा.', 'तूप गरम करून जिरे व कढीपत्ता घाला, मग प्युरी ओता.', 'ओले खोबरे, मीठ व टोमॅटो आंबट असतील तर थोडा गूळ किंवा साखर घाला.', '८–१० मिनिटे उकळा आणि पाणी घालून सारासारखे पातळ करा.', 'गरम भातावर वाढा.'],
  'Matar paneer and chapati': ['पनीरचे तुकडे करून १० मिनिटे कोमट पाण्यात ठेवा म्हणजे मऊ राहतात.', 'तेलात कांदा सोनेरी होईपर्यंत परता; टोमॅटो व मसाले घालून तेल सुटेपर्यंत शिजवा; हवे असल्यास वाटून गुळगुळीत ग्रेव्ही करा.', 'मटार व एक वाटी पाणी घालून ८ मिनिटे मटार मऊ होईपर्यंत उकळा.', 'निथळलेले पनीर व मीठ घालून ३ मिनिटे उकळा.', 'चपातीसोबत गरम वाढा.'],
  'Dal palak and rice': ['तूरडाळ हळद घालून कुकरमध्ये मऊ शिजवून हलकी घोटा.', 'पालक धुवून चिरा.', 'तूप गरम करून जिरे व लसणाचे काप घाला, मग पालक २–३ मिनिटे परता.', 'डाळ, मीठ व गरजेनुसार पाणी घालून ५ मिनिटे उकळा.', 'गरम भातासोबत वाढा.'],
  'Batata vada': ['बटाटे उकडून कुस्करा; थोड्या तेलात मोहरी, लसूण व मिरचीची फोडणी करून मीठासह मिसळा.', 'लिंबाएवढे गोळे करा.', 'बेसन, मीठ व पाणी घालून घट्ट पीठ भिजवा.', 'प्रत्येक गोळा पिठात बुडवून मध्यम आचेवर सोनेरी होईपर्यंत तळा.', 'निथळून चटणीसोबत गरम वाढा.'],
  'Samosa': ['गव्हाचे पीठ, तेल, मीठ व पाणी घालून घट्ट कणीक मळा; २० मिनिटे ठेवा.', 'बटाटे उकडून कुस्करा; मटार, जिरे, मिरची व मीठ घालून परतून सारण करा आणि थंड होऊ द्या.', 'कणीक पातळ लाटून अर्धी कापा; प्रत्येकाचा कोन करून सारण भरा आणि कडा पाण्याने बंद करा.', 'मंद ते मध्यम आचेवर १०–१२ मिनिटे कुरकुरीत व सोनेरी होईपर्यंत तळा.', 'निथळून चटणीसोबत गरम वाढा.'],
  'Corn chaat': ['मक्याचे दाणे चिमूटभर मीठ घालून मऊ उकडून निथळा.', 'कोमट दाण्यांना थोडे लोणी लावून परता.', 'चिरलेला कांदा, टोमॅटो व कोथिंबीर घाला.', 'लिंबाचा रस व मीठ घालून चव करा.', 'लगेच वाढा.'],
  'Mutton curry and bhakri': ['मटण धुवून आले-लसूण, मीठ व हळद लावून किमान १ तास फ्रिजमध्ये मुरवा.', 'तेलात कांदा तपकिरी होईपर्यंत परता; गोडा मसाला व टोमॅटो घालून तेल सुटेपर्यंत शिजवा.', 'मटण घालून ५–८ मिनिटे परतून घ्या.', 'गरम पाणी घालून झाकून कुकरमध्ये किंवा भांड्यात ४०–६० मिनिटे मटण पूर्ण मऊ व शिजेपर्यंत शिजवा.', 'हवे असल्यास ओल्या खोबऱ्याचे वाटण घालून ५ मिनिटे उकळा आणि भाकरीसोबत वाढा.'],
  'Kolhapuri mutton and rice': ['मटणाला आले-लसूण व मीठ लावून किमान १ तास फ्रिजमध्ये मुरवा.', 'सुक्या लाल मिरच्या, खोबरे व मसाले कोरडे भाजून कांद्यासह वाटून झणझणीत कोल्हापुरी मसाला करा.', 'कांदा गडद सोनेरी परतून मसाला घाला आणि तेल सुटून रंग गडद होईपर्यंत परता.', 'मटण व गरम पाणी घालून कुकरमध्ये किंवा भांड्यात ४०–६० मिनिटे अगदी मऊ व शिजेपर्यंत शिजवा.', 'गरम भातासोबत वाढा (लहान मुलांसाठी तिखट कमी ठेवा).'],
  'Mutton biryani and raita': ['मटणाला दही, आले-लसूण, मीठ व मसाले लावून किमान २ तास फ्रिजमध्ये मुरवा.', 'तुपात कांदा गडद सोनेरी तळा; निम्मा बाजूला ठेवा.', 'मुरवलेले मटण कांदा व थोडे पाणी घालून सुमारे पाऊण शिजेपर्यंत शिजवा.', 'बासमती तांदूळ खडे मसाले घालून ७०% शिजवा; मटणावर थर लावून राखलेला कांदा घाला.', 'घट्ट झाकण ठेवून मंद आचेवर २५–३० मिनिटे शिजवा; मटण पूर्ण मऊ असल्याची खात्री करून रायत्यासोबत वाढा.'],
  'Chicken sukka and chapati': ['चिकनला आले-लसूण, मीठ व हळद लावून ३० मिनिटे फ्रिजमध्ये ठेवा.', 'खोबरे व मसाले गडद होईपर्यंत कोरडे भाजून जाडसर वाटा.', 'तेलात कांदा सोनेरी परतून चिकन घालून १० मिनिटे ढवळत शिजवा.', 'वाटण व थोडे पाणी घालून झाकून चिकन पूर्ण शिजेपर्यंत व रस्सा कोरडा होईपर्यंत शिजवा.', 'चपातीसोबत गरम वाढा.'],
  'Mutton kheema and pav': ['खिमा धुवून स्वयंपाकापर्यंत फ्रिजमध्ये ठेवा.', 'तेलात कांदा सोनेरी परता; आले-लसूण, टोमॅटो व मसाले घालून तेल सुटेपर्यंत शिजवा.', 'खिमा घालून जास्त आचेवर ५ मिनिटे गुठळ्या मोडत परता.', 'मटार व थोडे पाणी घालून झाकून २५–३० मिनिटे खिमा पूर्ण शिजेपर्यंत व कोरडा होईपर्यंत शिजवा.', 'पाव तव्यावर भाजून गरम खिम्यासोबत वाढा.'],
  'Mutton pulao and raita': ['मटणाला दही, आले-लसूण व मीठ लावून किमान १ तास फ्रिजमध्ये मुरवा.', 'खडे मसाले व कांदा सोनेरी परतून मटण घालून १० मिनिटे शिजवा.', 'गरम पाणी घालून कुकरमध्ये किंवा भांड्यात ३०–४० मिनिटे मटण जवळजवळ मऊ होईपर्यंत शिजवा.', 'धुतलेला तांदूळ व योग्य प्रमाणात पाणी (तांदळाच्या सुमारे दीडपट) घालून झाकून भात व मटण पूर्ण शिजवा.', '५ मिनिटे ठेवून रायत्यासोबत वाढा.'],
  'Egg bhurji and chapati': ['अंडी चिमूटभर मीठ घालून फेटा.', 'तेलात कांदा, हिरवी मिरची व टोमॅटो मऊ होईपर्यंत परता.', 'फेटलेली अंडी घालून मध्यम आचेवर हळुवार ढवळा.', 'पूर्ण शिजेपर्यंत, पाणी राहणार नाही अशी शिजवून कोथिंबीर घाला.', 'चपातीसोबत गरम वाढा.'],
  'Prawn curry and rice': ['कोळंबी स्वच्छ करून शिरा काढा; मीठ व हळद लावून फ्रिजमध्ये ठेवा.', 'खोबरे, थोडी चिंच व मसाले वाटून पेस्ट करा.', 'कांदा सोनेरी परतून पेस्ट घालून ५ मिनिटे शिजवा.', 'पाणी घालून उकळी आणा; कोळंबी घालून फक्त ४–५ मिनिटे गुलाबी व अपारदर्शक होईपर्यंत शिजवा.', 'गरम भातासोबत वाढा.'],
  'Kashmiri rogan josh and rice': ['मटणाला दही, काश्मिरी तिखट, आले-लसूण व मीठ लावून किमान २ तास फ्रिजमध्ये मुरवा.', 'तूप किंवा तेल गरम करून खडे मसाले, मग चिरलेला कांदा गडद सोनेरी होईपर्यंत परता.', 'मुरवलेले मटण घालून जास्त आचेवर ८–१० मिनिटे ढवळत तपकिरी होईपर्यंत व तेल सुटेपर्यंत शिजवा.', 'गरम पाणी घालून झाकून ४५–६० मिनिटे उकळा किंवा कुकरमध्ये शिजवा; मटण पूर्ण मऊ व शिजले पाहिजे.', 'झाकण काढून ५ मिनिटे उकळून घट्ट लाल रस्सा करा आणि भातासोबत वाढा.'],
  'Saoji mutton and chapati': ['मटणाला आले-लसूण व मीठ लावून किमान १ तास फ्रिजमध्ये मुरवा.', 'सुक्या लाल मिरच्या, खोबरे, खसखस, तीळ व खडे मसाले वेगवेगळे गडद व सुगंधी होईपर्यंत कोरडे भाजा; तळलेल्या कांद्यासह वाटून घट्ट सावजी मसाला करा.', 'तेल गरम करून मसाला तेल सुटेपर्यंत व रंग गडद होईपर्यंत नीट परता.', 'मटण व गरम पाणी घालून ४५–६० मिनिटे कुकरमध्ये किंवा भांड्यात पूर्ण मऊ व शिजेपर्यंत शिजवा.', 'चपातीसोबत गरम वाढा (खूप तिखट; लहान मुलांसाठी मिरच्या कमी करा).'],
  'Mutton sukka and bhakri': ['मटणाला आले-लसूण, मीठ व हळद लावून किमान १ तास फ्रिजमध्ये मुरवा.', 'मटण थोड्या पाण्यात ३०–४० मिनिटे कुकरमध्ये किंवा भांड्यात जवळजवळ मऊ होईपर्यंत शिजवा.', 'सुक्या लाल मिरच्या, खोबरे व मसाले कोरडे भाजून जाडसर वाटा.', 'तेलात कांदा सोनेरी परतून वाटलेला मसाला सुगंध येईपर्यंत परता.', 'मटण त्याच्या पाण्यासह घालून झाकण न ठेवता रस्सा कोरडा व मटण पूर्ण मऊ होईपर्यंत शिजवा; भाकरीसोबत वाढा.'],
  'Mutton chops masala and chapati': ['मटण चॉप्स धुवून दही, आले-लसूण, मसाले व मीठ लावून किमान २ तास फ्रिजमध्ये मुरवा.', 'चॉप्स थोड्या पाण्यात कुकरमध्ये २०–२५ मिनिटे मऊ होईपर्यंत शिजवा; पाणी (स्टॉक) राखून ठेवा.', 'तेलात कांदा-टोमॅटो परतून घट्ट मसाला करा.', 'चॉप्स व थोडा स्टॉक घालून १० मिनिटे मसाला चॉप्सला लागेपर्यंत शिजवा.', 'जास्त आचेवर थोडा वेळ परतून तपकिरी करा आणि चपातीसोबत गरम वाढा.'],
  'Mutton handi and chapati': ['मटणाला दही, आले-लसूण व मीठ लावून किमान २ तास फ्रिजमध्ये मुरवा.', 'जाड भांड्यात (हंडी) तूप गरम करून खडे मसाले व कांदा सोनेरी होईपर्यंत परता.', 'मटण व टोमॅटो घालून जास्त आचेवर ८–१० मिनिटे तेल सुटेपर्यंत शिजवा.', 'गरम पाणी घालून घट्ट झाकून मंद आचेवर ५०–६० मिनिटे मटण पूर्ण मऊ होईपर्यंत शिजवा.', 'हंडीतूनच चपातीसोबत गरम वाढा.'],
  'Kheema pulao and raita': ['खिमा धुवून दही, आले-लसूण व मीठ लावून ३० मिनिटे फ्रिजमध्ये ठेवा.', 'तेलात खडे मसाले व चिरलेला कांदा सोनेरी परता.', 'खिमा घालून जास्त आचेवर ८ मिनिटे गुठळ्या मोडत शिजवा; मटार घाला.', 'धुतलेला तांदूळ व पाणी (तांदळाच्या सुमारे दीडपट) घालून झाकून मंद आचेवर भात व खिमा पूर्ण शिजेपर्यंत शिजवा.', '५ मिनिटे ठेवून मोकळा करा आणि रायत्यासोबत वाढा.'],
};
